// src/laboratories/executions/http.ts
function laboratoriesExecutionsCreateLaboratoryExecution(client, body, options) {
  if (body.stream) {
    return client.post_streaming(
      "laboratories/executions",
      body,
      options
    );
  }
  return client.post_unary(
    "laboratories/executions",
    body,
    options
  );
}
